-- generated by: python -m kestrel_m2.warehouse --print-ddl
CREATE SCHEMA IF NOT EXISTS kestrel_dw;

-- Lab 6 source-file catalogue: one row per file content (file@sha256)
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_source_file (
    source_file_id text NOT NULL,
    file_name text NOT NULL,
    path text NOT NULL,
    format text NOT NULL,
    format_detail text NOT NULL,
    grain text NOT NULL,
    size_bytes bigint NOT NULL,
    content_sha256 char(64) NOT NULL,
    row_count bigint NOT NULL,
    used_in text NOT NULL,
    ingested_at timestamptz NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source_file_id)
);

-- calendar built from the data's own timestamps (UTC days)
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_date (
    date_key integer NOT NULL,
    full_date date NOT NULL,
    year smallint NOT NULL,
    quarter smallint NOT NULL,
    month smallint NOT NULL,
    month_name text NOT NULL,
    day smallint NOT NULL,
    day_of_week smallint NOT NULL,
    day_name text NOT NULL,
    iso_year smallint NOT NULL,
    iso_week smallint NOT NULL,
    is_weekend boolean NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (date_key)
);

-- minute of the UTC day (0..1439) with 6-hour bands
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_time (
    time_key smallint NOT NULL,
    hour smallint NOT NULL,
    minute smallint NOT NULL,
    hhmm char(5) NOT NULL,
    hour_band text NOT NULL,
    is_business_hours boolean NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (time_key)
);

-- canonical tenants (tn_004 merged into tn_003)
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_tenant (
    tenant_id text NOT NULL,
    tenant_name text NOT NULL,
    industry text NOT NULL,
    plan_tier text NOT NULL,
    region text,
    region_raw text,
    onboarded_at_utc timestamptz NOT NULL,
    is_active boolean NOT NULL,
    security_contact text,
    merged_tenant_ids text[] NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

-- one row per agent version (Type-2 window kept as columns)
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_agent (
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    release_version_raw text NOT NULL,
    agent_name text NOT NULL,
    agent_type text NOT NULL,
    model_id text NOT NULL,
    tenant_id text NOT NULL,
    sandbox_profile_id text NOT NULL,
    owner_team text NOT NULL,
    autonomy_level text NOT NULL,
    max_tool_calls_per_session integer NOT NULL,
    launch_date date NOT NULL,
    is_deprecated boolean NOT NULL,
    valid_from_utc timestamptz NOT NULL,
    valid_to_utc timestamptz,
    is_current boolean NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (agent_id, release_version),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS dim_agent_ix0 ON kestrel_dw.dim_agent (agent_sk);

CREATE TABLE IF NOT EXISTS kestrel_dw.dim_tool (
    tool_id text NOT NULL,
    tool_version text NOT NULL,
    tool_name text NOT NULL,
    tool_category text NOT NULL,
    risk_tier text NOT NULL,
    requires_approval boolean NOT NULL,
    owner_team text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tool_id, tool_version),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

-- one row per policy version, flattened in DuckDB; validity dates are ordinary columns
CREATE TABLE IF NOT EXISTS kestrel_dw.dim_policy (
    sandbox_profile_id text NOT NULL,
    policy_version integer NOT NULL,
    valid_from_utc timestamptz NOT NULL,
    valid_to_utc timestamptz,
    valid_to_declared_utc timestamptz,
    allowed_tools text[] NOT NULL,
    has_network_block boolean NOT NULL,
    egress_allowlist text[] NOT NULL,
    denied_ports integer[] NOT NULL,
    max_egress_mb double precision,
    fs_read_scope text[] NOT NULL,
    fs_write_scope text[] NOT NULL,
    max_runtime_s integer NOT NULL,
    max_memory_mb integer NOT NULL,
    escalation_allowed boolean NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (sandbox_profile_id, policy_version),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE TABLE IF NOT EXISTS kestrel_dw.policy_allowed_tool (
    sandbox_profile_id text NOT NULL,
    policy_version integer NOT NULL,
    tool_id text NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (sandbox_profile_id, policy_version, tool_id),
    FOREIGN KEY (sandbox_profile_id, policy_version) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version)
);

CREATE TABLE IF NOT EXISTS kestrel_dw.policy_egress_rule (
    sandbox_profile_id text NOT NULL,
    policy_version integer NOT NULL,
    allowlist_entry text NOT NULL,
    is_wildcard boolean NOT NULL,
    match_regex text NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (sandbox_profile_id, policy_version, allowlist_entry),
    FOREIGN KEY (sandbox_profile_id, policy_version) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version)
);

CREATE TABLE IF NOT EXISTS kestrel_dw.dim_model_price (
    model_id text NOT NULL,
    effective_from_utc timestamptz NOT NULL,
    effective_to_utc timestamptz,
    model_family text NOT NULL,
    input_price_per_1k numeric(12,6),
    output_price_per_1k numeric(12,6),
    currency text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (model_id, effective_from_utc),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

-- one row per accepted session (accumulating snapshot of the whole session)
CREATE TABLE IF NOT EXISTS kestrel_dw.fact_session (
    session_id text NOT NULL,
    tenant_id text NOT NULL,
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    sandbox_profile_id text,
    policy_version_applied integer,
    sandbox_instance_id text NOT NULL,
    task_id text NOT NULL,
    task_category text NOT NULL,
    expected_tool_categories text NOT NULL,
    start_time_utc timestamptz NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    end_time_utc timestamptz,
    terminal_event_type text,
    outcome text,
    duration_s double precision,
    terminal_latency_ms bigint,
    latency_disagrees boolean,
    n_events integer NOT NULL,
    n_prompt_turns integer NOT NULL,
    n_tool_calls integer NOT NULL,
    n_tool_violations integer NOT NULL,
    n_tool_denied integer NOT NULL,
    n_tool_failed integer NOT NULL,
    n_network_flows integer NOT NULL,
    n_egress_violations integer NOT NULL,
    n_distinct_destinations integer NOT NULL,
    n_sandbox_decisions integer NOT NULL,
    n_sandbox_denials integer NOT NULL,
    n_escalation_attempts integer NOT NULL,
    n_escalation_denied integer NOT NULL,
    n_injection_turns integer NOT NULL,
    n_late_events integer NOT NULL,
    has_sequence_gap boolean NOT NULL,
    is_trace_complete boolean NOT NULL,
    executed_tool_categories text NOT NULL,
    is_goal_drift boolean,
    first_injection_time_utc timestamptz,
    first_violation_time_utc timestamptz,
    first_violation_after_injection_utc timestamptz,
    tokens_in bigint,
    tokens_out bigint,
    cost_usd numeric(14,6),
    start_activity_id text NOT NULL,
    terminal_activity_id text,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (sandbox_profile_id, policy_version_applied) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS fact_session_ix0 ON kestrel_dw.fact_session (tenant_id);

CREATE INDEX IF NOT EXISTS fact_session_ix1 ON kestrel_dw.fact_session (agent_id, release_version);

CREATE INDEX IF NOT EXISTS fact_session_ix2 ON kestrel_dw.fact_session (date_key);

CREATE TABLE IF NOT EXISTS kestrel_dw.fact_prompt_turn (
    event_id text NOT NULL,
    activity_id text NOT NULL,
    session_id text NOT NULL,
    tenant_id text NOT NULL,
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    sandbox_profile_id text,
    policy_version_applied integer,
    event_time_utc timestamptz NOT NULL,
    ingest_time_utc timestamptz NOT NULL,
    lateness_s double precision NOT NULL,
    is_late boolean NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    sequence_number integer NOT NULL,
    turn_index integer NOT NULL,
    status text NOT NULL,
    latency_ms bigint NOT NULL,
    model_id text NOT NULL,
    content_source text NOT NULL,
    stated_goal text NOT NULL,
    injection_indicators text NOT NULL,
    n_injection_indicators smallint NOT NULL,
    finish_reason text NOT NULL,
    tokens_in bigint NOT NULL,
    tokens_out bigint,
    input_price_per_1k numeric(12,6),
    output_price_per_1k numeric(12,6),
    cost_usd numeric(14,6),
    event_time_format text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (event_id),
    FOREIGN KEY (session_id) REFERENCES kestrel_dw.fact_session (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (sandbox_profile_id, policy_version_applied) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS fact_prompt_turn_ix0 ON kestrel_dw.fact_prompt_turn (session_id);

CREATE INDEX IF NOT EXISTS fact_prompt_turn_ix1 ON kestrel_dw.fact_prompt_turn (date_key);

CREATE INDEX IF NOT EXISTS fact_prompt_turn_ix2 ON kestrel_dw.fact_prompt_turn (agent_id, release_version);

CREATE TABLE IF NOT EXISTS kestrel_dw.fact_tool_call (
    event_id text NOT NULL,
    activity_id text NOT NULL,
    session_id text NOT NULL,
    tenant_id text NOT NULL,
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    sandbox_profile_id text,
    policy_version_applied integer,
    event_time_utc timestamptz NOT NULL,
    ingest_time_utc timestamptz NOT NULL,
    lateness_s double precision NOT NULL,
    is_late boolean NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    sequence_number integer NOT NULL,
    tool_id text NOT NULL,
    tool_version text NOT NULL,
    tool_id_raw text NOT NULL,
    status text NOT NULL,
    status_raw text NOT NULL,
    error_class text,
    retry_number integer NOT NULL,
    latency_ms bigint NOT NULL,
    finished_at_utc timestamptz NOT NULL,
    target_resource text NOT NULL,
    bytes_out bigint,
    is_policy_violation boolean,
    risk_indicators text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (event_id),
    FOREIGN KEY (session_id) REFERENCES kestrel_dw.fact_session (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (sandbox_profile_id, policy_version_applied) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id),
    FOREIGN KEY (tool_id, tool_version) REFERENCES kestrel_dw.dim_tool (tool_id, tool_version)
);

CREATE INDEX IF NOT EXISTS fact_tool_call_ix0 ON kestrel_dw.fact_tool_call (session_id);

CREATE INDEX IF NOT EXISTS fact_tool_call_ix1 ON kestrel_dw.fact_tool_call (date_key);

CREATE INDEX IF NOT EXISTS fact_tool_call_ix2 ON kestrel_dw.fact_tool_call (agent_id, release_version);

CREATE INDEX IF NOT EXISTS fact_tool_call_ix3 ON kestrel_dw.fact_tool_call (tool_id, tool_version);

CREATE TABLE IF NOT EXISTS kestrel_dw.fact_network_flow (
    flow_id text NOT NULL,
    activity_id text NOT NULL,
    session_id text NOT NULL,
    tenant_id text NOT NULL,
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    sandbox_profile_id text,
    policy_version_applied integer,
    flow_time_utc timestamptz NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    sandbox_instance_id text NOT NULL,
    src_ip text NOT NULL,
    dst_host text,
    dst_host_raw text,
    dst_ip text NOT NULL,
    dst_port integer NOT NULL,
    protocol text NOT NULL,
    bytes_sent bigint NOT NULL,
    bytes_received bigint NOT NULL,
    verdict text NOT NULL,
    geo_country text,
    is_policy_violation boolean,
    violation_rule text NOT NULL,
    risk_indicators text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (flow_id),
    FOREIGN KEY (session_id) REFERENCES kestrel_dw.fact_session (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (sandbox_profile_id, policy_version_applied) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS fact_network_flow_ix0 ON kestrel_dw.fact_network_flow (session_id);

CREATE INDEX IF NOT EXISTS fact_network_flow_ix1 ON kestrel_dw.fact_network_flow (src_ip, dst_ip, dst_port);

CREATE TABLE IF NOT EXISTS kestrel_dw.fact_sandbox_decision (
    audit_id text NOT NULL,
    activity_id text NOT NULL,
    session_id text NOT NULL,
    tenant_id text NOT NULL,
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer NOT NULL,
    sandbox_profile_id text,
    policy_version_applied integer,
    event_time_utc timestamptz NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    log_time_raw text NOT NULL,
    host text NOT NULL,
    host_offset_s double precision NOT NULL,
    process text NOT NULL,
    pid integer NOT NULL,
    sandbox_instance_id text NOT NULL,
    decision text NOT NULL,
    action text NOT NULL,
    is_escalation_action boolean NOT NULL,
    target text NOT NULL,
    reason text NOT NULL,
    policy_version_reported integer,
    is_policy_violation boolean,
    violation_rule text NOT NULL,
    risk_indicators text NOT NULL,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (audit_id),
    FOREIGN KEY (session_id) REFERENCES kestrel_dw.fact_session (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (sandbox_profile_id, policy_version_applied) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS fact_sandbox_decision_ix0 ON kestrel_dw.fact_sandbox_decision (session_id);

CREATE INDEX IF NOT EXISTS fact_sandbox_decision_ix1 ON kestrel_dw.fact_sandbox_decision (date_key);

-- severity is the targeted system's opinion, carried as received
CREATE TABLE IF NOT EXISTS kestrel_dw.fact_siem_alert (
    alert_id text NOT NULL,
    activity_id text NOT NULL,
    detected_at_utc timestamptz NOT NULL,
    date_key integer NOT NULL,
    time_key smallint NOT NULL,
    detected_at_raw text NOT NULL,
    utc_offset text NOT NULL,
    source_system text NOT NULL,
    severity text NOT NULL,
    source_ip text NOT NULL,
    destination_host text NOT NULL,
    destination_port integer NOT NULL,
    technique_id text NOT NULL,
    technique_name text,
    rule text NOT NULL,
    confidence double precision NOT NULL,
    match_status text NOT NULL,
    n_candidate_flows integer NOT NULL,
    n_candidate_sessions integer NOT NULL,
    matched_flow_id text,
    session_id text,
    session_resolution text NOT NULL,
    delta_s double precision,
    tenant_id text,
    agent_id text,
    release_version text,
    quality_flags text NOT NULL,
    source_file_id text NOT NULL,
    source_line bigint NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (alert_id),
    FOREIGN KEY (session_id) REFERENCES kestrel_dw.fact_session (session_id),
    FOREIGN KEY (tenant_id) REFERENCES kestrel_dw.dim_tenant (tenant_id),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version),
    FOREIGN KEY (date_key) REFERENCES kestrel_dw.dim_date (date_key),
    FOREIGN KEY (time_key) REFERENCES kestrel_dw.dim_time (time_key),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id),
    FOREIGN KEY (matched_flow_id) REFERENCES kestrel_dw.fact_network_flow (flow_id)
);

CREATE INDEX IF NOT EXISTS fact_siem_alert_ix0 ON kestrel_dw.fact_siem_alert (session_id);

CREATE INDEX IF NOT EXISTS fact_siem_alert_ix1 ON kestrel_dw.fact_siem_alert (source_ip, destination_host, destination_port);

-- every refused record (batch and stream), exactly one enum reason, pointer to file and line
CREATE TABLE IF NOT EXISTS kestrel_dw.fact_rejected_record (
    source_file text NOT NULL,
    source_line bigint NOT NULL,
    source_file_id text NOT NULL,
    source_format text NOT NULL,
    record_id text,
    reason text NOT NULL CHECK (reason IN ('DUPLICATE_EVENT_ID', 'UNKNOWN_AGENT_ID', 'UNKNOWN_TENANT_ID', 'MALFORMED_TIMESTAMP', 'ORPHAN_EVENT', 'INVALID_EVENT_TYPE', 'MISSING_REQUIRED_FIELD', 'INVALID_NUMERIC_RANGE', 'LATE_BEYOND_WATERMARK', 'UNPARSEABLE_RECORD', 'SCHEMA_VIOLATION')),
    reason_detail text,
    raw_payload text NOT NULL,
    zone text NOT NULL,
    channel text NOT NULL,
    detected_by text NOT NULL,
    kafka_topic text,
    kafka_partition integer,
    kafka_offset bigint,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (source_file, source_line),
    FOREIGN KEY (source_file_id) REFERENCES kestrel_dw.dim_source_file (source_file_id)
);

CREATE INDEX IF NOT EXISTS fact_rejected_record_ix0 ON kestrel_dw.fact_rejected_record (reason);

CREATE INDEX IF NOT EXISTS fact_rejected_record_ix1 ON kestrel_dw.fact_rejected_record (channel);

CREATE TABLE IF NOT EXISTS kestrel_dw.stream_curated_event (
    event_id text PRIMARY KEY,
    event_type text NOT NULL,
    session_id text NOT NULL,
    sequence_number integer NOT NULL,
    event_time_utc timestamptz NOT NULL,
    ingest_time_utc timestamptz NOT NULL,
    lateness_s double precision NOT NULL,
    is_late boolean NOT NULL,
    tenant_id text NOT NULL REFERENCES kestrel_dw.dim_tenant (tenant_id),
    agent_id text NOT NULL,
    release_version text NOT NULL,
    agent_sk integer,
    sandbox_instance_id text NOT NULL,
    status text NOT NULL,
    latency_ms bigint,
    model_id text,
    content_source text,
    stated_goal_fingerprint text,
    injection_indicators text,
    tokens_in bigint,
    tokens_out bigint,
    finish_reason text,
    tool_id text,
    tool_version text,
    finished_at_utc timestamptz,
    retry_number integer,
    error_class text,
    target_resource text,
    bytes_out bigint,
    task_id text,
    task_category text,
    expected_tool_categories text,
    quality_flags text NOT NULL,
    source_file text NOT NULL,
    source_line bigint NOT NULL,
    kafka_partition integer NOT NULL,
    kafka_offset bigint NOT NULL,
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version)
);
CREATE TABLE IF NOT EXISTS kestrel_dw.stream_message_log (
    kafka_topic text NOT NULL,
    kafka_partition integer NOT NULL,
    kafka_offset bigint NOT NULL,
    event_id text,
    session_id text,
    source_line bigint,
    outcome text NOT NULL,
    reason text,
    processed_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (kafka_topic, kafka_partition, kafka_offset)
);
CREATE TABLE IF NOT EXISTS kestrel_dw.stream_tenant_minute (
    tenant_id text NOT NULL,
    window_start timestamptz NOT NULL,
    window_end timestamptz NOT NULL,
    events bigint NOT NULL,
    tool_calls bigint NOT NULL,
    denied_tool_calls bigint NOT NULL,
    is_final boolean NOT NULL,
    late_updates integer NOT NULL DEFAULT 0,
    PRIMARY KEY (tenant_id, window_start)
);

-- Aggregate tables of the warehouse (refreshed by aggregates.sql, delete-then-insert).
-- Rates are numeric(9,6) fractions (0..1) so a refresh is bit-for-bit reproducible.

CREATE TABLE IF NOT EXISTS kestrel_dw.agent_daily_behaviour (
    date_key integer NOT NULL REFERENCES kestrel_dw.dim_date (date_key),
    agent_id text NOT NULL,
    release_version text NOT NULL,
    sessions_started integer NOT NULL,
    sessions_terminal integer NOT NULL,
    sessions_success integer NOT NULL,
    sessions_error integer NOT NULL,
    prompt_turns integer NOT NULL,
    injection_turns integer NOT NULL,
    tool_calls integer NOT NULL,
    tool_violations integer NOT NULL,
    tool_denied integer NOT NULL,
    tool_failed integer NOT NULL,
    tool_retries integer NOT NULL,
    network_flows integer NOT NULL,
    egress_violations integer NOT NULL,
    sandbox_decisions integer NOT NULL,
    sandbox_denials integer NOT NULL,
    escalation_attempts integer NOT NULL,
    tokens_in bigint NOT NULL,
    tokens_out bigint NOT NULL,
    cost_usd numeric(14,6) NOT NULL,
    session_error_rate numeric(9,6),
    tool_violation_rate numeric(9,6),
    egress_violation_rate numeric(9,6),
    injection_turn_rate numeric(9,6),
    PRIMARY KEY (date_key, agent_id, release_version),
    FOREIGN KEY (agent_id, release_version) REFERENCES kestrel_dw.dim_agent (agent_id, release_version)
);

CREATE TABLE IF NOT EXISTS kestrel_dw.tenant_risk_metrics (
    tenant_id text PRIMARY KEY REFERENCES kestrel_dw.dim_tenant (tenant_id),
    sessions integer NOT NULL,
    terminal_sessions integer NOT NULL,
    session_error_rate numeric(9,6),
    tool_calls integer NOT NULL,
    tool_violations integer NOT NULL,
    tool_violation_rate numeric(9,6),
    network_flows integer NOT NULL,
    egress_violations integer NOT NULL,
    egress_violation_rate numeric(9,6),
    sandbox_decisions integer NOT NULL,
    sandbox_denials integer NOT NULL,
    sandbox_denial_rate numeric(9,6),
    escalation_denied_sessions integer NOT NULL,
    prompt_turns integer NOT NULL,
    injection_turns integer NOT NULL,
    injection_turn_rate numeric(9,6),
    goal_drift_sessions integer NOT NULL,
    goal_drift_rate numeric(9,6),
    injection_then_violation_sessions integer NOT NULL,
    siem_alerts_linked integer NOT NULL,
    siem_alerts_high_critical integer NOT NULL,
    tokens_in bigint NOT NULL,
    tokens_out bigint NOT NULL,
    cost_usd numeric(14,6) NOT NULL
);

CREATE TABLE IF NOT EXISTS kestrel_dw.policy_violation_metrics (
    sandbox_profile_id text NOT NULL,
    policy_version integer NOT NULL,
    activity_type text NOT NULL,
    records integer NOT NULL,
    violations integer NOT NULL,
    violation_rate numeric(9,6),
    sessions_with_violation integer NOT NULL,
    rule_breakdown text NOT NULL,
    PRIMARY KEY (sandbox_profile_id, policy_version, activity_type),
    FOREIGN KEY (sandbox_profile_id, policy_version) REFERENCES kestrel_dw.dim_policy (sandbox_profile_id, policy_version)
);

CREATE TABLE IF NOT EXISTS kestrel_dw.data_quality_metrics (
    channel text NOT NULL,
    source_file text NOT NULL,
    metric text NOT NULL,
    code text NOT NULL,
    records bigint NOT NULL,
    denominator bigint NOT NULL,
    rate numeric(9,6),
    PRIMARY KEY (channel, source_file, metric, code)
);
